import './styles.css';
import { useState } from 'react';

interface Category {
  id: string;
  title: string;
  icon: string;
  color: string;
  questions: Question[];
}

interface Question {
  id: string;
  text: string;
  guidance: string;
}

interface Answer {
  status: 'yes' | 'no' | 'unsure' | null;
  notes: string;
}

const categories: Category[] = [
  {
    id: 'purpose',
    title: 'Purpose & Fit',
    icon: '🎯',
    color: '#6366f1',
    questions: [
      {
        id: 'right-tool',
        text: 'Is a chatbot the right tool for this problem?',
        guidance: 'Consider whether human connection, complex judgment, or relationship-building are core to the work. If so, a chatbot may not be appropriate.',
      },
      {
        id: 'clear-goal',
        text: 'Is there a clear, specific goal for the chatbot?',
        guidance: 'Vague goals like "improve engagement" often lead to poor outcomes. Define exactly what the chatbot should accomplish.',
      },
      {
        id: 'simpler-solution',
        text: 'Have you ruled out simpler solutions?',
        guidance: 'Sometimes an FAQ page, phone hotline, or trained staff can solve the problem better than a chatbot.',
      },
    ],
  },
  {
    id: 'risk',
    title: 'Risk Assessment',
    icon: '⚠️',
    color: '#ef4444',
    questions: [
      {
        id: 'worst-case',
        text: 'Have you identified worst-case scenarios if the chatbot fails?',
        guidance: 'What happens if the bot gives wrong information? Consider health, safety, legal, and emotional risks.',
      },
      {
        id: 'vulnerable-users',
        text: 'Have you assessed risks to vulnerable users?',
        guidance: 'People in crisis, with limited literacy, or in dangerous situations may be particularly harmed by chatbot errors.',
      },
      {
        id: 'human-escalation',
        text: 'Is there a clear path to human support?',
        guidance: 'Users must be able to reach a human when the chatbot cannot help, especially for sensitive or urgent matters.',
      },
    ],
  },
  {
    id: 'accuracy',
    title: 'Accuracy & Quality',
    icon: '✓',
    color: '#10b981',
    questions: [
      {
        id: 'accuracy-testing',
        text: 'Can you test the chatbot with realistic scenarios?',
        guidance: 'Test with actual users and edge cases, not just ideal scenarios. Include users who are not tech-savvy.',
      },
      {
        id: 'language-support',
        text: 'Does the chatbot work in languages your users actually speak?',
        guidance: 'Many AI systems work poorly in languages other than English. Test thoroughly in all needed languages.',
      },
      {
        id: 'content-verification',
        text: 'How will you verify the accuracy of chatbot responses?',
        guidance: 'Establish processes to review and correct chatbot information regularly, especially for time-sensitive content.',
      },
    ],
  },
  {
    id: 'privacy',
    title: 'Data & Privacy',
    icon: '🔒',
    color: '#f59e0b',
    questions: [
      {
        id: 'data-sensitivity',
        text: 'Do you understand what data the chatbot will collect?',
        guidance: 'Chatbots often collect sensitive information. Know exactly what data flows where.',
      },
      {
        id: 'data-protection',
        text: 'Are appropriate data protection measures in place?',
        guidance: 'Consider encryption, access controls, retention policies, and legal requirements like GDPR.',
      },
      {
        id: 'informed-consent',
        text: 'Will users understand how their data is used?',
        guidance: 'Clear, accessible privacy notices are essential. Users should know they are talking to a bot.',
      },
    ],
  },
  {
    id: 'capacity',
    title: 'Organizational Capacity',
    icon: '🏢',
    color: '#8b5cf6',
    questions: [
      {
        id: 'technical-capacity',
        text: 'Do you have capacity to build/maintain the chatbot?',
        guidance: 'Chatbots require ongoing maintenance, content updates, and technical support. This is not a one-time project.',
      },
      {
        id: 'human-backup',
        text: 'Do you have staff capacity for human backup?',
        guidance: 'Someone needs to handle escalations, review conversations, and respond when the bot fails.',
      },
      {
        id: 'monitoring',
        text: 'Can you monitor chatbot performance and problems?',
        guidance: 'You need to know when the chatbot is giving bad answers or users are frustrated.',
      },
    ],
  },
];

function QuestionItem({
  question,
  answer,
  onAnswer,
}: {
  question: Question;
  answer: Answer;
  onAnswer: (status: Answer['status'], notes: string) => void;
}) {
  const [showNotes, setShowNotes] = useState(false);

  return (
    <div className={`question-item ${answer.status || ''}`}>
      <div className="question-text">{question.text}</div>
      <div className="question-guidance">{question.guidance}</div>

      <div className="response-row">
        <div className="response-buttons">
          <button
            className={`response-btn yes ${answer.status === 'yes' ? 'selected' : ''}`}
            onClick={() => onAnswer('yes', answer.notes)}
          >
            Yes
          </button>
          <button
            className={`response-btn unsure ${answer.status === 'unsure' ? 'selected' : ''}`}
            onClick={() => onAnswer('unsure', answer.notes)}
          >
            Unsure
          </button>
          <button
            className={`response-btn no ${answer.status === 'no' ? 'selected' : ''}`}
            onClick={() => onAnswer('no', answer.notes)}
          >
            No
          </button>
        </div>
        <button 
          className="notes-toggle"
          onClick={() => setShowNotes(!showNotes)}
        >
          {showNotes ? '− Notes' : '+ Notes'}
        </button>
      </div>

      {showNotes && (
        <textarea
          className="notes-input"
          placeholder="Add your notes here..."
          value={answer.notes}
          onChange={(e) => onAnswer(answer.status, e.target.value)}
        />
      )}
    </div>
  );
}

function CategorySection({
  category,
  answers,
  onAnswer,
}: {
  category: Category;
  answers: Record<string, Answer>;
  onAnswer: (questionId: string, status: Answer['status'], notes: string) => void;
}) {
  const [expanded, setExpanded] = useState(true);

  const stats = category.questions.reduce(
    (acc, q) => {
      const status = answers[q.id]?.status;
      if (status === 'yes') acc.yes++;
      else if (status === 'no') acc.no++;
      else if (status === 'unsure') acc.unsure++;
      else acc.unanswered++;
      return acc;
    },
    { yes: 0, no: 0, unsure: 0, unanswered: 0 }
  );

  return (
    <div className="category-section">
      <div 
        className="category-header"
        style={{ borderLeftColor: category.color }}
        onClick={() => setExpanded(!expanded)}
      >
        <div className="category-title">
          <span className="category-icon">{category.icon}</span>
          <span>{category.title}</span>
        </div>
        <div className="category-stats">
          {stats.yes > 0 && <span className="stat-badge yes">{stats.yes} ✓</span>}
          {stats.no > 0 && <span className="stat-badge no">{stats.no} ✗</span>}
          {stats.unsure > 0 && <span className="stat-badge unsure">{stats.unsure} ?</span>}
          <span className="expand-icon">{expanded ? '▼' : '▶'}</span>
        </div>
      </div>

      {expanded && (
        <div className="category-questions">
          {category.questions.map((question) => (
            <QuestionItem
              key={question.id}
              question={question}
              answer={answers[question.id] || { status: null, notes: '' }}
              onAnswer={(status, notes) => onAnswer(question.id, status, notes)}
            />
          ))}
        </div>
      )}
    </div>
  );
}

function Summary({ answers }: { answers: Record<string, Answer> }) {
  const allQuestions = categories.flatMap((c) => c.questions);
  const stats = allQuestions.reduce(
    (acc, q) => {
      const status = answers[q.id]?.status;
      if (status === 'yes') acc.yes++;
      else if (status === 'no') acc.no++;
      else if (status === 'unsure') acc.unsure++;
      else acc.unanswered++;
      return acc;
    },
    { yes: 0, no: 0, unsure: 0, unanswered: 0 }
  );

  const total = allQuestions.length;
  const answered = total - stats.unanswered;
  const readinessScore = Math.round((stats.yes / total) * 100);

  let status = 'incomplete';
  let statusMessage = 'Complete all questions for a full assessment.';
  let statusColor = '#6b7280';

  if (stats.unanswered === 0) {
    if (stats.no > 2) {
      status = 'not-ready';
      statusMessage = 'Significant concerns need to be addressed before proceeding.';
      statusColor = '#ef4444';
    } else if (stats.no > 0 || stats.unsure > 3) {
      status = 'needs-work';
      statusMessage = 'Some areas need attention. Address concerns before moving forward.';
      statusColor = '#f59e0b';
    } else if (stats.unsure > 0) {
      status = 'almost-ready';
      statusMessage = 'Good progress! Resolve remaining uncertainties before proceeding.';
      statusColor = '#3b82f6';
    } else {
      status = 'ready';
      statusMessage = 'You\'ve addressed key considerations. Proceed thoughtfully!';
      statusColor = '#10b981';
    }
  }

  return (
    <div className="summary-panel" style={{ borderColor: statusColor }}>
      <h2>Assessment Summary</h2>

      <div className="progress-bar-container">
        <div className="progress-bar">
          <div className="progress-fill" style={{ width: `${(answered / total) * 100}%` }} />
        </div>
        <span className="progress-text">{answered}/{total} answered</span>
      </div>

      <div className="stats-row">
        <div className="stat-item yes">
          <span className="stat-num">{stats.yes}</span>
          <span className="stat-label">Ready</span>
        </div>
        <div className="stat-item unsure">
          <span className="stat-num">{stats.unsure}</span>
          <span className="stat-label">Unsure</span>
        </div>
        <div className="stat-item no">
          <span className="stat-num">{stats.no}</span>
          <span className="stat-label">Concern</span>
        </div>
      </div>

      <div className="status-box" style={{ backgroundColor: statusColor + '15', borderColor: statusColor }}>
        <p style={{ color: statusColor }}>{statusMessage}</p>
      </div>

      {stats.no > 0 && (
        <div className="concerns-list">
          <strong>Areas needing attention:</strong>
          <ul>
            {categories.flatMap((c) =>
              c.questions
                .filter((q) => answers[q.id]?.status === 'no')
                .map((q) => <li key={q.id}>{q.text}</li>)
            )}
          </ul>
        </div>
      )}
    </div>
  );
}

export default function App() {
  const [answers, setAnswers] = useState<Record<string, Answer>>({});

  const handleAnswer = (questionId: string, status: Answer['status'], notes: string) => {
    setAnswers((prev) => ({
      ...prev,
      [questionId]: { status, notes },
    }));
  };

  return (
    <div className="app">
      <header className="header">
        <h1>Chatbot Adoption Checklist</h1>
        <p className="subtitle">
          Work through these considerations before designing or deploying a chatbot
        </p>
      </header>

      <div className="main-content">
        <div className="questions-column">
          {categories.map((category) => (
            <CategorySection
              key={category.id}
              category={category}
              answers={answers}
              onAnswer={handleAnswer}
            />
          ))}
        </div>

        <div className="summary-column">
          <Summary answers={answers} />

          <div className="resource-box">
            <h3>Key Resources</h3>
            <ul>
              <li>Chatbots in Humanitarian Contexts (The Engine Room)</li>
              <li>Considerations before designing & adopting chatbots (The Engine Room)</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #1e3a5f 0%, #2d5a87 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 1100px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.95rem;
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 1.5rem;
}

@media (max-width: 900px) {
  .main-content {
    grid-template-columns: 1fr;
  }
  .summary-column {
    order: -1;
  }
}

.questions-column {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.category-section {
  background: white;
  border-radius: 0.75rem;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.category-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem;
  border-left: 4px solid;
  cursor: pointer;
  background: #f9fafb;
}

.category-header:hover {
  background: #f3f4f6;
}

.category-title {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 600;
  color: #1f2937;
}

.category-icon {
  font-size: 1.25rem;
}

.category-stats {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.stat-badge {
  font-size: 0.7rem;
  padding: 0.15rem 0.4rem;
  border-radius: 0.25rem;
  font-weight: 600;
}

.stat-badge.yes { background: #d1fae5; color: #047857; }
.stat-badge.no { background: #fee2e2; color: #b91c1c; }
.stat-badge.unsure { background: #fef3c7; color: #b45309; }

.expand-icon {
  color: #9ca3af;
  font-size: 0.75rem;
  margin-left: 0.5rem;
}

.category-questions {
  padding: 0.5rem 1rem 1rem;
}

.question-item {
  padding: 1rem;
  border: 1px solid #e5e7eb;
  border-radius: 0.5rem;
  margin-bottom: 0.75rem;
  transition: all 0.2s;
}

.question-item:last-child {
  margin-bottom: 0;
}

.question-item.yes { border-left: 3px solid #10b981; }
.question-item.no { border-left: 3px solid #ef4444; }
.question-item.unsure { border-left: 3px solid #f59e0b; }

.question-text {
  font-weight: 500;
  color: #1f2937;
  margin-bottom: 0.5rem;
  font-size: 0.95rem;
}

.question-guidance {
  color: #6b7280;
  font-size: 0.85rem;
  line-height: 1.4;
  margin-bottom: 0.75rem;
}

.response-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.75rem;
}

.response-buttons {
  display: flex;
  gap: 0.5rem;
}

.response-btn {
  padding: 0.4rem 0.75rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.375rem;
  background: white;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s;
}

.response-btn.yes:hover, .response-btn.yes.selected {
  background: #d1fae5;
  border-color: #10b981;
  color: #047857;
}

.response-btn.unsure:hover, .response-btn.unsure.selected {
  background: #fef3c7;
  border-color: #f59e0b;
  color: #b45309;
}

.response-btn.no:hover, .response-btn.no.selected {
  background: #fee2e2;
  border-color: #ef4444;
  color: #b91c1c;
}

.notes-toggle {
  padding: 0.3rem 0.6rem;
  border: 1px solid #d1d5db;
  border-radius: 0.25rem;
  background: white;
  font-size: 0.75rem;
  color: #6b7280;
  cursor: pointer;
}

.notes-toggle:hover {
  background: #f3f4f6;
}

.notes-input {
  width: 100%;
  min-height: 60px;
  padding: 0.5rem;
  border: 1px solid #e5e7eb;
  border-radius: 0.375rem;
  font-size: 0.85rem;
  margin-top: 0.75rem;
  resize: vertical;
}

.notes-input:focus {
  outline: none;
  border-color: #3b82f6;
}

/* Summary Panel */
.summary-column {
  position: sticky;
  top: 1.5rem;
  height: fit-content;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.summary-panel {
  background: white;
  border-radius: 0.75rem;
  padding: 1.25rem;
  border-top: 4px solid;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.summary-panel h2 {
  font-size: 1rem;
  color: #1f2937;
  margin-bottom: 1rem;
}

.progress-bar-container {
  margin-bottom: 1rem;
}

.progress-bar {
  height: 8px;
  background: #e5e7eb;
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 0.25rem;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #3b82f6, #6366f1);
  transition: width 0.3s;
}

.progress-text {
  font-size: 0.75rem;
  color: #6b7280;
}

.stats-row {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.stat-item {
  flex: 1;
  text-align: center;
  padding: 0.5rem;
  border-radius: 0.5rem;
}

.stat-item.yes { background: #d1fae5; }
.stat-item.unsure { background: #fef3c7; }
.stat-item.no { background: #fee2e2; }

.stat-num {
  display: block;
  font-size: 1.25rem;
  font-weight: 700;
}

.stat-item.yes .stat-num { color: #047857; }
.stat-item.unsure .stat-num { color: #b45309; }
.stat-item.no .stat-num { color: #b91c1c; }

.stat-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  color: #6b7280;
}

.status-box {
  padding: 0.75rem;
  border-radius: 0.5rem;
  border: 1px solid;
  margin-bottom: 0.75rem;
}

.status-box p {
  font-size: 0.85rem;
  font-weight: 500;
  margin: 0;
}

.concerns-list {
  font-size: 0.8rem;
  background: #fef2f2;
  padding: 0.75rem;
  border-radius: 0.5rem;
}

.concerns-list strong {
  display: block;
  color: #991b1b;
  margin-bottom: 0.5rem;
}

.concerns-list ul {
  list-style: none;
  padding-left: 0;
}

.concerns-list li {
  color: #b91c1c;
  padding-left: 1rem;
  position: relative;
  margin-bottom: 0.25rem;
}

.concerns-list li::before {
  content: '!';
  position: absolute;
  left: 0;
  font-weight: bold;
}

.resource-box {
  background: white;
  border-radius: 0.75rem;
  padding: 1rem;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.resource-box h3 {
  font-size: 0.9rem;
  color: #1f2937;
  margin-bottom: 0.75rem;
}

.resource-box ul {
  list-style: none;
  padding-left: 0;
}

.resource-box li {
  font-size: 0.8rem;
  color: #4b5563;
  padding: 0.25rem 0;
  padding-left: 1rem;
  position: relative;
}

.resource-box li::before {
  content: '→';
  position: absolute;
  left: 0;
  color: #9ca3af;
}
